# UAOS V1715 RP alias safety fix
# PowerShell has built-in alias RP = Remove-ItemProperty.
# This block removes that alias and defines RP as relative-path helper for this script.
try {
    if (Test-Path Alias:RP) {
        Remove-Item Alias:RP -Force -ErrorAction SilentlyContinue
    }
} catch {}

function RP {
    param(
        [string]$Base,
        [string]$Full
    )
    try {
        $b = [System.IO.Path]::GetFullPath($Base).TrimEnd([char]'\',[char]'/')
        $f = [System.IO.Path]::GetFullPath($Full)
        if ($f.StartsWith($b, [System.StringComparison]::OrdinalIgnoreCase)) {
            return $f.Substring($b.Length).TrimStart([char]'\',[char]'/')
        }
        return $Full
    } catch {
        return $Full
    }
}

