function SN($n){ $out=""; $bad=[IO.Path]::GetInvalidFileNameChars(); foreach($ch in $n.ToCharArray()){ if($bad -contains $ch){$out+="_"}else{$out+=$ch} }; $out=$out -replace "\s+","_"; if([string]::IsNullOrWhiteSpace($out)){"sample"}else{$out} }
